        "qa",
        "lh",
        "lt",
        "le",
        "oq",
        "mr", "mg", "mh", "ms", "mx", "rh", "rt", "rr", "ra", "ma", "mo", "lp", "pa", "ph", "xa", "xh", "xg", "xp",
        "na",
        "ce", "ci", "cl", "al", "ai", "ad", "cb", "cu", "cv", "ct", "cd", "pd", "hd",
        "cp", "cq", "ca",
        "fs", "fx", "fr", "fi", "ft", "oi", "od",
        "fb", "fp", "fq", "fd", "fc",
        "br",
        "hm", "fm", "fh",
        "fa", "fe", "ah",
        "ea", "eh",
        "ts", "tm", "te", "tk", "tg", "tx",
        "ep", "fw",
        "ru",
        "mu",
    ):
        fail(EXIT_INPUT, "INPUT")

    keys = set(raw_op)
    if name == "add":
